    const empty = !relevant.length ? `尚无${category === 'fuel' ? '加油' : '充电'}记录，请先记录一次${category === 'fuel' ? '加油' : '充电'}。` : relevant.every(item => item.excludedFromEnergy) ? '全部补能记录已排除，请恢复至少一条记录。' : `尚未形成完整${category === 'fuel' ? '加满' : '充满'}区间，请至少记录两次${category === 'fuel' ? '加满' : '充满'}且里程递增的补能。`
